'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import {varianceOutcomes,prepareVarianceRequest,varianceArgs,readVarianceReceipt,readVarianceStatus,loadVarianceRequest,saveVarianceRequest,clearVarianceRequest,type VarianceRequest,type VarianceScope} from '@/lib/cashier-variance';
export function CashierVarianceAction({scope,revision,onSaved}:{scope:VarianceScope;revision:string;onSaved:()=>void}){
 const [pending,setPending]=useState<VarianceRequest|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState(''),[confirmed,setConfirmed]=useState(false);const alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;try{setPending(loadVarianceRequest(sessionStorage,scope))}catch(e){setError(e instanceof Error?e.message:'Unable to recover review.')}return()=>{alive.current=false}},[scope.tenant,scope.property,scope.session,scope.actor]);
 async function submit(mode:'save'|'status'|'cancel',request:VarianceRequest|null=pending){if(lock.current||!request||(mode==='cancel'&&!confirmed))return;lock.current=true;setBusy(true);setError('');setMessage('');try{
  const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen variance review.');if(!alive.current)return;
  saveVarianceRequest(sessionStorage,request);setPending(request);
  const args={p_tenant:scope.tenant,p_property:scope.property,p_request:request.request};
  const result=await hotelRpc(mode==='save'?'review_cashier_variance':mode==='status'?'cashier_variance_status':'cancel_cashier_variance_request',mode==='save'?varianceArgs(request):mode==='cancel'?{...args,p_confirmed:true}:args);
  const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Recover after signing in.');if(!alive.current)return;
  if(mode==='save')readVarianceReceipt(result,request);else if(mode==='status'){if(!readVarianceStatus(result,request)){setMessage('No saved result found. Retry the original review or cancel it.');return}}else{const r=result as Record<string,unknown>;if(!r||r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.request_id!==request.request||r.cancelled!==true||typeof r.replayed!=='boolean')throw Error('Cancellation receipt does not match this review.')}
  clearVarianceRequest(sessionStorage,request);setPending(null);setConfirmed(false);setMessage(mode==='cancel'?'Unrecorded review cancelled.':'Variance review saved.');onSaved();
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Review interrupted. Check its saved result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section><h4>Record manager review</h4>{pending?<><p>Pending review: {pending.outcome.replaceAll('_',' ')} — {pending.reason}</p><button disabled={busy} onClick={()=>void submit('save')}>Retry variance review</button><button disabled={busy} onClick={()=>void submit('status')}>Check variance result</button><label><input type="checkbox" disabled={busy} checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>Cancel only if this review was not recorded</label><button disabled={busy||!confirmed} onClick={()=>void submit('cancel')}>Cancel unrecorded variance review</button></>:<form onSubmit={e=>{e.preventDefault();try{const f=new FormData(e.currentTarget);const r=prepareVarianceRequest(scope,crypto.randomUUID(),revision,String(f.get('outcome')),String(f.get('reason')).trim());void submit('save',r)}catch(e){setError(e instanceof Error?e.message:'Review the details.')}}}><fieldset disabled={busy}><label className="field">Review outcome<select name="outcome">{varianceOutcomes.map(x=><option key={x} value={x}>{x.replaceAll('_',' ')}</option>)}</select></label><label className="field">Review explanation<textarea name="reason" required minLength={4} maxLength={500}/></label><label><input type="checkbox" required/>I reviewed the cash difference. This records my assessment without posting an accounting adjustment.</label><button>Save variance review</button></fieldset></form>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>
}